102	                    ((Number) project.get("clientId")).longValue(), status, archived, budget,
103	                    codeValue);
104	        }
105	        List<Map<String, Object>> tasks =
106	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
107	        for (Map<String, Object> task : tasks) {
108	            Object done = task.getOrDefault("done", Boolean.FALSE);
109	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
110	                    ((Number) task.get("id")).longValue(),
111	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
112	                    Boolean.TRUE.equals(done));
113	        }
114	        List<Map<String, Object>> notes =
115	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
116	        long maxNoteId = 0;
117	        for (Map<String, Object> note : notes) {
118	            long noteId = ((Number) note.get("id")).longValue();
119	            maxNoteId = Math.max(maxNoteId, noteId);
120	            jdbc.update(
121	                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
122	                    noteId, note.get("targetType"),
123	                    ((Number) note.get("targetId")).longValue(), note.get("text"),
124	                    java.sql.Timestamp.from(parseInstant(note.get("at").toString())));
