136	        }
137	        List<Map<String, Object>> projectTags =
138	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
139	        for (Map<String, Object> projectTag : projectTags) {
140	            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
141	                    ((Number) projectTag.get("projectId")).longValue(),
142	                    ((Number) projectTag.get("tagId")).longValue());
143	        }
144	        List<Map<String, Object>> contacts =
145	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
146	        for (Map<String, Object> contact : contacts) {
