1	import React, { useEffect, useState } from 'react';
2	import { ClientSummary } from './ClientSummary';
3	import { ClientStatement } from './ClientStatement';
4	import { ClientPayment } from './ClientPayment';
5	import { ClientProjects } from './ClientProjects';
6	import { ClientContacts } from './ClientContacts';
7	
8	// The clients feature owns its own state, data loading and layout (no global store). It lists every
9	// client and adds a new one by name + email.
10	type Client = { id: number; name: string; email: string };
11	
12	// A proper email: something, '@', something, '.', something — no whitespace. Matches the server
13	// (CreateClientLogic) and schema (V2) checks so the three layers agree on what is acceptable.
14	const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
15	
16	export function ClientsPage() {
17	  const [clients, setClients] = useState<Client[]>([]);
18	  const [name, setName] = useState('');
19	  const [email, setEmail] = useState('');
20	  const [emailError, setEmailError] = useState('');
21	  const [search, setSearch] = useState('');
22	  // How the list is ordered: by name (A–Z) or by how much each client owes (most first).
23	  const [sort, setSort] = useState<'name' | 'outstanding'>('name');
24	  // Per-client outstanding totals, keyed by client id, for the "owes" ordering.
25	  const [outstanding, setOutstanding] = useState<Record<number, number>>({});
26	  const [openClientId, setOpenClientId] = useState<number | null>(null);
27	  // Whether the archived (tucked-away) clients are being shown instead of the active list.
28	  const [showArchived, setShowArchived] = useState(false);
29	  // The archived clients, for the "show archived" view where they can be brought back.
30	  const [archivedClients, setArchivedClients] = useState<Client[]>([]);
31	
32	  // The client currently being corrected from the list, plus the edited field values.
33	  const [editingClientId, setEditingClientId] = useState<number | null>(null);
34	  const [editName, setEditName] = useState('');
35	  const [editEmail, setEditEmail] = useState('');
36	  const [editError, setEditError] = useState('');
37	
38	  async function load() {
39	    const res = await fetch('/api/clients');
40	    setClients(await res.json());
41	    const arch = await fetch('/api/clients/archived');
42	    setArchivedClients(await arch.json());
43	    const owed = await fetch('/api/clients/outstanding');
44	    const rows: { id: number; outstanding: number }[] = await owed.json();
45	    setOutstanding(Object.fromEntries(rows.map((r) => [r.id, Number(r.outstanding)])));
46	  }
47	
48	  useEffect(() => {
49	    void load();
50	  }, []);
51	
52	  async function onSubmit(e: React.FormEvent) {
53	    e.preventDefault();
54	
55	    // Every client needs a proper email — block the save and surface the error if it is missing or
56	    // malformed, so no row is created.
57	    if (!EMAIL.test(email.trim())) {
58	      setEmailError('A proper email address is required');
59	      return;
60	    }
61	    setEmailError('');
62	
63	    const res = await fetch('/api/clients', {
64	      method: 'POST',
65	      headers: { 'Content-Type': 'application/json' },
66	      body: JSON.stringify({ name, email: email.trim() }),
67	    });
68	    if (!res.ok) {
69	      // A 409 means the email is already taken by another client; anything else is a bad address.
70	      setEmailError(
71	        res.status === 409
72	          ? 'A client with this email already exists'
73	          : 'A proper email address is required',
74	      );
75	      return;
76	    }
77	    setName('');
78	    setEmail('');
79	    await load();
80	  }
81	
82	  // Tuck a client away: archive it so it drops off this list and the search while being retained.
83	  async function onArchive(id: number) {
84	    await fetch(`/api/clients/${id}/archive`, { method: 'POST' });
85	    await load();
86	  }
87	
88	  // Bring a tucked-away client back: clear its archived flag so it returns to the main list.
89	  async function onRestore(id: number) {
90	    await fetch(`/api/clients/${id}/restore`, { method: 'POST' });
91	    await load();
92	  }
93	
94	  // Open the inline edit form for a client, pre-filled with its current name and email.
95	  function onEdit(c: Client) {
96	    setEditingClientId(c.id);
97	    setEditName(c.name);
98	    setEditEmail(c.email);
99	    setEditError('');
