3	// A client's statement, rendered inside the clients feature when a client is opened: all of that
4	// client's invoices (gathered from every one of their projects) in one place, each with how much is
5	// still left to pay, and the outstanding total — what they still owe across those invoices. Opens on
6	// demand (client-statement-open) and then reads /api/clients/<id>/statement. Owns its own state and
7	// data loading (no global store); composed, not branched.
8	type StatementInvoice = {
9	  id: number;
10	  projectId: number;
11	  amount: number;
12	  due: number;
13	  status: string;
14	};
15	
16	type StatementGroup = {
17	  projectId: number;
18	  projectName: string;
19	  invoices: StatementInvoice[];
20	  subtotal: number;
21	};
22	
23	type Statement = {
24	  invoices: StatementInvoice[];
25	  groups: StatementGroup[];
26	  outstandingTotal: number;
27	};
28	
29	function formatAmount(amount: number): string {
30	  return `$${Number(amount).toLocaleString('en-US', {
31	    minimumFractionDigits: 2,
32	    maximumFractionDigits: 2,
33	  })}`;
34	}
35	
36	export function ClientStatement({ clientId }: { clientId: number }) {
37	  const [statement, setStatement] = useState<Statement | null>(null);
38	
39	  // Collapse the statement when the opened client changes, so it is opened fresh per client.
40	  useEffect(() => {
41	    setStatement(null);
42	  }, [clientId]);
43	
44	  async function open() {
45	    const res = await fetch(`/api/clients/${clientId}/statement`);
46	    if (!res.ok) {
47	      return;
48	    }
49	    setStatement(await res.json());
50	  }
51	
52	  return (
53	    <section data-testid="client-statement">
54	      <button type="button" data-testid="client-statement-open" onClick={() => void open()}>
55	        Statement
56	      </button>
57	
58	      {statement ? (
59	       <>
60	        <table data-testid="client-statement-table">
61	          <thead>
62	            <tr>
63	              <th>Invoice</th>
64	              <th>Amount</th>
65	              <th>Due</th>
66	              <th>Status</th>
67	            </tr>
68	          </thead>
69	          {statement.groups.map((group) => (
70	            <tbody
71	              key={group.projectId}
72	              data-testid={`statement-project-${group.projectId}`}
73	            >
74	              <tr>
75	                <th colSpan={4} data-testid="statement-project-name">
76	                  {group.projectName}
77	                </th>
78	              </tr>
79	              {group.invoices.map((inv) => (
80	                <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
81	                  <td data-testid="statement-invoice-id">{inv.id}</td>
82	                  <td data-testid="statement-invoice-amount">{formatAmount(inv.amount)}</td>
83	                  <td data-testid="statement-invoice-due">{formatAmount(inv.due)}</td>
84	                  <td data-testid="statement-invoice-status">{inv.status}</td>
85	                </tr>
86	              ))}
87	              <tr>
88	                <td>Subtotal</td>
89	                <td data-testid="statement-project-subtotal" colSpan={3}>
90	                  {formatAmount(group.subtotal)}
91	                </td>
92	              </tr>
93	            </tbody>
94	          ))}
95	          <tfoot>
96	            <tr>
97	              <td>Outstanding</td>
98	              <td data-testid="client-outstanding-total" colSpan={3}>
99	                {formatAmount(statement.outstandingTotal)}
100	              </td>
101	            </tr>
102	          </tfoot>
103	        </table>
104	
105	        {/* A clean, printable summary of the statement: each job's invoices listed plainly with
106	            what is still owed, closing on the grand total the client owes across everything. This
107	            is the "print this and hand it over" view; the grand total is the outstanding total
108	            (what is still due across all of their invoices). */}
109	        <section data-testid="statement-print-view">
110	          <h2>Statement summary</h2>
111	          {statement.groups.map((group) => (
112	            <div key={group.projectId} data-testid={`statement-print-project-${group.projectId}`}>
113	              <h3 data-testid="statement-print-project-name">{group.projectName}</h3>
114	              <ul>
115	                {group.invoices.map((inv) => (
116	                  <li key={inv.id} data-testid={`statement-print-invoice-${inv.id}`}>
117	                    Invoice #{inv.id}: {formatAmount(inv.due)} due
118	                  </li>
119	                ))}
