35	  const [code, setCode] = useState('');
36	  const [codeError, setCodeError] = useState('');
37	  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
38	  // While an invoice is opened, its own notes take over the notes surface, so the project's notes
39	  // step aside (they share the note-* testids and would otherwise be a second notes surface).
40	  const [invoiceOpen, setInvoiceOpen] = useState(false);
