43	  const [filterStatus, setFilterStatus] = useState('');
44	
45	  async function load() {
46	    const [pRes, cRes, tRes] = await Promise.all([
47	      fetch('/api/projects'),
48	      fetch('/api/clients'),
49	      fetch('/api/tags'),
50	    ]);
51	    setProjects(await pRes.json());
52	    setClients(await cRes.json());
53	    setTags(await tRes.json());
54	  }
55	
56	  useEffect(() => {
57	    void load();
58	  }, []);
59	
60	  async function remove(projectId: number) {
61	    const res = await fetch(`/api/projects/${projectId}`, { method: 'DELETE' });
62	    if (!res.ok) {
63	      return;
64	    }
65	    if (openProjectId === projectId) {
66	      setOpenProjectId(null);
67	    }
68	    await load();
69	  }
70	
71	  // Archiving tucks a project away: it drops off the list unless archived ones are revealed, and is
72	  // retained (the server keeps the row, just flagged). Delete still removes a project outright.
73	  async function archive(projectId: number) {
74	    const res = await fetch(`/api/projects/${projectId}/archive`, { method: 'POST' });
75	    if (!res.ok) {
76	      return;
77	    }
78	    if (openProjectId === projectId) {
79	      setOpenProjectId(null);
80	    }
81	    await load();
82	  }
83	
84	  async function onSubmit(e: React.FormEvent) {
